import{_ as t,o,c as a,aa as r}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/en/diary/en_prehledy_new.jpg",n="/buildary-help-preview/media/en/diary/en_prehledy_pocasi.jpg",s="/buildary-help-preview/media/en/diary/en_zobrazit_tlacitko.jpg",m=JSON.parse('{"title":"Reports","description":"","frontmatter":{"title":"Reports","wiki":"en:diary:reports"},"headers":[],"relativePath":"en/diary/reports.md","filePath":"en/diary/reports.md","lastUpdated":1793088561000}'),d={name:"en/diary/reports.md"};function l(h,e,p,c,g,y){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h1><p>The <strong>Reports</strong> option in the left navigation bar allows you to display data from the selected Project Diary in a grid format.</p><h2 id="data-content" tabindex="-1">Data Content <a class="header-anchor" href="#data-content" aria-label="Permalink to &quot;Data Content&quot;">​</a></h2><p>Reports are organized into <strong>sections</strong>.</p><p>For each section, you can choose how the data should be grouped. The available grouping options vary slightly between sections depending on the data contained in each section.</p><p>For example, in the <strong>Labour</strong> section, there are 5 data grouping options. Grouping <strong>by Contractor</strong> provides the highest-level overview, while grouping <strong>by Contractor, Profession, Last Name and First Name</strong> provides the most detailed overview, including subtotals for each level, as shown in the image below.</p><img src="'+i+'" alt="Persons on Site report grouped by Supplier, Profession, Last Name and First Name" width="600" loading="lazy"><h3 id="what-is-displayed" tabindex="-1">What Is Displayed <a class="header-anchor" href="#what-is-displayed" aria-label="Permalink to &quot;What Is Displayed&quot;">​</a></h3><p>Depending on the report section, the <strong>View by</strong> switch allows you to choose between displaying <strong>Hours</strong> (for Persons and Machinery), <strong>Quantity</strong> (for practically all sections), or <strong>Quantity of entries</strong> (for Materials and Works Performed).</p><p>For Labour, <strong>Quantity</strong> indicates the number of days on which a particular person was present on the project. In aggregated views, it indicates how many people were present on the project on a given day. Quantity does not take working hours into account, so each person is always counted as 1, regardless of whether they worked for one hour or the entire day.</p><h3 id="weather" tabindex="-1">Weather <a class="header-anchor" href="#weather" aria-label="Permalink to &quot;Weather&quot;">​</a></h3><p>The Weather section behaves differently from the other sections. Reports in this section are designed to identify instances where specific meteorological conditions occurred.</p><p>For example, if you want to find instances where the temperature was below 5°C, configure the settings as shown in the image below:</p><img src="'+n+'" alt="Weather Report" width="600" loading="lazy"><h2 id="period" tabindex="-1">Period <a class="header-anchor" href="#period" aria-label="Permalink to &quot;Period&quot;">​</a></h2><p>Each report allows you to select the period for which you want to display data.</p><p>Depending on the selected period, the level of detail displayed in the columns is automatically determined according to the following rules:</p><ul><li>If the user selects a time period shorter than 32 days, the data in the columns will be displayed <strong>by day</strong>. Therefore, a maximum of one month can be displayed by day.</li><li>If the user selects a time period from 32 days to 36 months, the data in the columns will be displayed <strong>by month</strong>. Therefore, a maximum of 3 years can be displayed by month.</li><li>If the user selects a time period longer than 36 months, the data in the columns will be displayed <strong>by year</strong>.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Whenever you change any settings, you need to click the <img src="'+s+'" alt="" width="75" loading="lazy"> button to load the correct data.</p></div>',19)])])}const f=t(d,[["render",l]]);export{m as __pageData,f as default};
